/**
 * Analytics Backend - Dynamic Rust/WASM with TypeScript fallback
 *
 * Provides a unified interface to analytics with automatic fallback:
 * - Primary: Rust-based implementation via WASM for performance
 * - Fallback: Pure TypeScript implementation when WASM unavailable
 */
import { IndexAnalytics as TypeScriptIndexAnalytics } from './index-analytics.js';
/**
 * Analytics backend selector with dynamic WASM loading
 */
export class AnalyticsBackend {
    backend;
    wasmLoaded = false;
    constructor() {
        // Start with TypeScript backend, attempt WASM load async
        // Create a wrapper that implements the interface
        const tsBackend = new TypeScriptIndexAnalytics();
        this.backend = {
            recordIndexUsage: (name, op, time) => tsBackend.recordIndexUsage(name, op, time),
            recordQuery: (fields, op, time, rows, count, index) => tsBackend.recordQuery(fields, op, time, rows, count, index),
            getIndexMetrics: (name) => tsBackend.getIndexMetrics(name),
            getAllMetrics: () => tsBackend.getAllMetrics(),
            getSlowestQueries: (limit) => tsBackend.getSlowestQueries(limit),
            getFrequentFields: (limit) => tsBackend.getFrequentFields(limit),
            generateReport: (name, period) => tsBackend.generateReport(name, period),
            reset: () => tsBackend.reset(),
        };
        this.loadWasm().catch(() => {
            // Silently fail - TypeScript fallback is already in place
        });
    }
    async loadWasm() {
        if (this.wasmLoaded)
            return;
        try {
            // Dynamic import of WASM module when available
            // @ts-ignore - WASM module may not exist during development
            const wasmModule = await import('./wasm/feltdb_wasm.js');
            // Create WASM analytics instance
            const wasmAnalytics = new wasmModule.WasmAnalytics();
            // Replace backend with WASM implementation
            this.backend = new WasmAnalyticsAdapter(wasmAnalytics);
            this.wasmLoaded = true;
        }
        catch (error) {
            // WASM unavailable, continue with TypeScript
            // This is normal during development
        }
    }
    recordIndexUsage(index_name, operation, time_ms) {
        this.backend.recordIndexUsage(index_name, operation, time_ms);
    }
    recordQuery(fields, operator, executionTimeMs, rowsScanned, resultCount, indexUsed) {
        this.backend.recordQuery(fields, operator, executionTimeMs, rowsScanned, resultCount, indexUsed);
    }
    getIndexMetrics(index_name) {
        return this.backend.getIndexMetrics(index_name);
    }
    getAllMetrics() {
        return this.backend.getAllMetrics();
    }
    getSlowestQueries(limit) {
        return this.backend.getSlowestQueries(limit);
    }
    getFrequentFields(limit) {
        return this.backend.getFrequentFields(limit);
    }
    generateReport(collectionName, period) {
        return this.backend.generateReport(collectionName, period);
    }
    reset() {
        this.backend.reset();
    }
}
/**
 * Adapter to bridge WASM analytics to TypeScript interface
 */
class WasmAnalyticsAdapter {
    wasm;
    constructor(wasm) {
        this.wasm = wasm;
    }
    recordIndexUsage(index_name, operation, time_ms) {
        this.wasm.record_index_usage(index_name, operation, time_ms);
    }
    recordQuery(fields, operator, executionTimeMs, rowsScanned, resultCount, indexUsed) {
        this.wasm.record_query(JSON.stringify(fields), operator, executionTimeMs, BigInt(rowsScanned), BigInt(resultCount), indexUsed || null);
    }
    getIndexMetrics(index_name) {
        try {
            const json = this.wasm.get_index_metrics(index_name);
            return JSON.parse(json);
        }
        catch {
            return null;
        }
    }
    getAllMetrics() {
        try {
            const json = this.wasm.get_all_metrics();
            return JSON.parse(json);
        }
        catch {
            return [];
        }
    }
    getSlowestQueries(limit) {
        try {
            const json = this.wasm.get_slowest_queries(limit);
            return JSON.parse(json);
        }
        catch {
            return [];
        }
    }
    getFrequentFields(limit) {
        try {
            const json = this.wasm.get_frequent_fields(limit);
            return JSON.parse(json);
        }
        catch {
            return [];
        }
    }
    generateReport(collectionName, period) {
        try {
            const json = this.wasm.generate_report(collectionName, period);
            return JSON.parse(json);
        }
        catch {
            return {
                collectionName,
                period,
                totalQueries: 0,
                indexedQueries: 0,
                fullScans: 0,
                avgQueryTimeMs: 0,
                indexMetrics: [],
                recommendations: [],
                timestamp: Date.now(),
            };
        }
    }
    reset() {
        this.wasm.reset();
    }
}
/**
 * Create analytics instance - internal use only
 */
export function createAnalyticsBackend() {
    return new AnalyticsBackend();
}
